/* Britannia-only learning profile. Product categories are not profit segments. */
(()=>{
 const id='britannia',c=window.COMPANIES.find(c=>c.id===id),previous=window.companyPrimer;
 const urls={company:'https://www.britannia.co.in/about-us',products:'https://www.britannia.co.in/',annual:'https://media.britannia.co.in/Britannia_Annual_Report_2025_26_High_Resolution_c738982760.pdf',investors:'https://www.britannia.co.in/investors/financial-performance/annual-report',cheese:'https://media.britannia.co.in/Press_Release_09_10_2024_747d4ea5a0.pdf'};
 const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const note=(url,label,location='')=>`<p class="source-note"><a href="${url}" target="_blank" rel="noopener">${label} ↗</a>${location?` · ${location}`:''}</p>`;
 c.summary='The packaged-food business behind Good Day, Marie Gold and Milk Bikis, with bread, cakes, rusk, dairy and other snacks alongside biscuits.';
 c.description='Britannia makes and sells packaged foods for everyday eating: biscuits with tea, bread for a meal, cakes and other snacks, and dairy products. Its business combines recipes and brands with ingredient sourcing, manufacturing, food safety and distribution so that a shopper can find a suitable pack and choose it again.';
 c.money='Britannia earns revenue by supplying packaged foods through distributors, retailers and online channels, in India and overseas. Ingredients, packaging, factory operations, delivery, promotions and the balance of products sold affect what remains after costs. More packs sold, a higher selling price and a shift to different products are different sources of growth.';
 window.COMPANY_OVERVIEWS[id]={customers:'Households buy through local shops, retail chains and online channels. A distributor or retailer buying from Britannia is different from the shopper who ultimately eats the food.',drivers:'Demand, pack sizes, prices, wheat, sugar, edible oils, milk and packaging costs. Freshness, distribution efficiency and the cost of developing newer food categories also matter.'};
 c.products=c.products.map(([name,type])=>[name,name==='NutriChoice'?'Biscuits and snacks':name==='Come Alive'?'Curd and yogurt':type]);
 for(const p of [['Bourbon Rolls','Filled wafer rolls'],['Britannia dairy ingredients and staples','Milk powder, butter, ghee and dairy whitener']])if(!c.products.some(([name])=>name===p[0]))c.products.push(p);
 c.productNote='Selected brand and offering families from the official portfolio and FY 2025–26 business review. Variants and pack sizes are grouped; this is not live inventory. Britannia The Laughing Cow cheese is associated with the Britannia Bel joint venture. Product categories do not have separately reported profits in the cited Foods segment note.';
 c.watch=[
  ['Are shoppers buying more food, or paying more for a different pack?','Separate quantities, pack sizes, price changes and a shift towards higher-priced products.'],
  ['Can pricing and efficiency keep up with ingredient costs?','Follow wheat, sugar, edible oils, milk and packaging alongside discounts and the stated margin measure.'],
  ['Are products reaching shoppers before they lose freshness?','Check distribution, stock returns, inventory and the economics of different shopping channels.'],
  ['Are newer categories building repeat demand and useful capacity?','Look beyond a launch announcement to the costs of dairy, croissants, wafers and other expansion.'],
  ['Are food quality and product claims protecting trust?','Use official evidence on safety, ingredients, labels and any regulatory or corrective action.'],
  ['Which entities and cash flows are included in the figures?','Read the group scope, cheese joint venture, overseas operations, cash generation and investment together.']
 ];
 window.COMPANY_RESEARCH_GUIDES[id]=[
  'Read sales and management’s quantity or volume commentary together. Compare equivalent weights where possible: more packs need not mean more food if packs become smaller. A premium product changes the sales mix but may also cost more to make and promote. Do not substitute revenue growth for an undisclosed volume-growth measure.',
  'Read the ingredient-cost and pricing discussion in the annual report and results commentary. Wheat, sugar, oils and milk have different cost cycles; stock bought earlier can delay the effect. Check promotions, transport, factory efficiency and advertising too. Compare the same profit definition across periods rather than assuming a higher shop price raises profit.',
  'Use revenue Note 53 for stock returns and discounts, promotions and channel margins; then read inventory, receivables and distribution commentary. General trade means local shops; modern trade means organised retail chains. Quick commerce adds another route to the shopper, with its own terms. More outlets or shipments into a channel do not prove that shoppers bought and consumed the goods.',
  'Follow the bakery, dairy and adjacent-business reviews alongside factory commissioning, utilisation and investment disclosures. Utilisation means the share of available production capability actually used. Ask whether customers return, whether stock moves and whether extra sales cover manufacturing, distribution and promotion. A new line or factory is capacity, not evidence of an attractive return.',
  'Read the company’s risk discussion, exchange filings and relevant official regulatory decisions. Identify the product, date, allegation or finding and the company’s response. Ingredients, storage and labelling requirements differ by offering. Brand positioning such as a health-oriented name is not by itself evidence of a nutritional benefit or protection from compliance risk.',
  'Start with standalone versus consolidated scope. The group reports one Foods operating segment; brands are not separate profit divisions. Read Notes 7 and 43 and the equity-method policy for the Britannia Bel joint venture. Then compare operating cash flow, capital spending, borrowings, dividends and related-party balances. Profit, cash collected and cash available to distribute are different measures.'
 ];
 c.risks=[
  ['Affordable packs leave limited room for cost increases','Ingredient and packaging inflation can reduce earnings. Raising prices, changing pack sizes or reducing promotions may help cover costs but can also cause shoppers to choose alternatives.'],
  ['Competition raises the cost of winning the next purchase','National brands, local bakeries and regional packaged-food businesses compete for shelf space and household spending. Advertising, discounts and new launches cost money before repeat demand is established.'],
  ['Food loses value if quality or freshness fails','Unsold or expired goods, damaged packaging and food-safety or labelling issues can cause returns, waste, disruption and lost trust. Storage requirements and shelf lives differ across biscuits, bread and dairy.'],
  ['New categories and facilities take time to earn enough','Dairy, snacking formats and manufacturing expansion need investment, distribution and consumer demand. Low utilisation or weak repeat purchases can leave costs running ahead of the benefits.'],
  ['Group complexity and overseas conditions affect the result','Joint ventures, overseas businesses, exchange rates and shipping disruptions can affect earnings and cash differently. A familiar brand name does not reveal how its business is included in the group accounts.']
 ];
 c.update=['Overseas sales bring different operating conditions','The FY 2025–26 business review describes temporary supply-chain disruption in the Middle East and higher freight and shipping costs. For Britannia’s international operations, read local demand and currency movements alongside logistics. Indian biscuit demand alone cannot explain every overseas market. This is context from that annual report, not a statement about current conditions.'];
 c.question='If Britannia sells more packs, has the business necessarily sold more food and earned more profit?';
 c.answer='No. Packs can change size, different products can make up the sales, and prices can change. Ingredients, promotions, distribution and new-category investment can use up the benefit of extra sales. Compare equivalent quantities where disclosed, the stated profit measure and cash generated before reaching a conclusion.';
 for(const p of [['FY 2025–26 annual report · business review and accounts',urls.annual],['Official annual-report library',urls.investors],['Britannia Bel cheese partnership · dated October 2024',urls.cheese],['Britannia business and product categories',urls.company]])if(!c.sources.some(([,url])=>url===p[1]))c.sources.push(p);
 const groups=[
  ['Biscuits and cookies','Good Day, Marie Gold, Milk Bikis, Tiger, NutriChoice, 50-50, Jim Jam and Bourbon illustrate different tastes, textures, prices and eating occasions.','The biscuit range covers tea-time purchases, sweet cookies, cream-filled products and savoury options. Recognising the eating occasion helps you understand which alternatives a shopper might choose.','Ingredients, pack affordability, promotions and availability influence the next purchase.'],
  ['Bread, cakes and rusk','Bread serves meal occasions; packaged cakes serve snacks and treats; Toastea rusk is a crisp, baked product often eaten with tea.','These sit within the bakery business, but the way they are made, stored and replenished differs. A bread loaf and a sealed biscuit pack should not be treated as identical distribution problems.','Freshness, shelf life, returns and how often outlets are supplied matter alongside sales.'],
  ['Dairy','The portfolio includes offerings such as Winkin’ Cow dairy drinks, Come Alive curd and yogurt, and Britannia The Laughing Cow cheese. The report also describes milk powder, butter, ghee and dairy whitener.','The cheese joint venture is explained later on this page. Not every dairy offering or business arrangement is the same.','Milk sourcing, processing, product-specific storage and distribution, and use of production capacity affect the economics.'],
  ['Other snacking formats','Treat Croissant and wafers, including the reported Bourbon Rolls format, extend the portfolio beyond familiar biscuits.','An adjacent category means a related area the company is developing. The same brand can appear on different food formats.','Ask whether new customers buy again and whether sales cover the extra production, distribution and promotion costs.']
 ];
 const basics=`<section class="content-section company-primer" id="britannia-basics"><div class="number">START WITH THE PRODUCTS</div><h2>Begin with the biscuit pack. Then look beyond it.</h2><p>A Good Day pack, a loaf of bread, a cake and a dairy drink serve different needs. Britannia’s job is to source ingredients, turn them into consistent food products, get them to the right outlet and persuade shoppers to buy again.</p><dl class="primer-definitions"><div><dt>Company → Britannia Industries</dt><dd>The food business behind a portfolio of brands and operations. Consolidated accounts cover the company and its subsidiaries, with joint ventures treated according to the accounting rules.</dd></div><div><dt>Brand → Good Day</dt><dd>A familiar name attached to a range of products. Different recipes and pack sizes can use that name.</dd></div><div><dt>Category → biscuits, bread or dairy</dt><dd>A way to understand what the company sells and how those products work. Categories can have different costs and distribution needs.</dd></div><div><dt>Reported operating segment → Foods</dt><dd>The group reports its operating performance as one Foods segment. The product categories below are not separately disclosed profit segments.</dd></div></dl>${note(urls.annual,'Britannia annual report','Business review and consolidated Note 43')}
 <h3>Connect familiar products to the business</h3><div class="primer-groups">${groups.map(([name,examples,meaning,drivers])=>`<div><h3>${name}</h3><p><strong>What it sells:</strong> ${examples}</p><p>${meaning}</p><p><strong>What to understand:</strong> ${drivers}</p></div>`).join('')}</div>${note(urls.annual,'Official product and business review','Bakery, Dairy and Adjacent Business reviews')}
 <h3>Who buys from Britannia, and who eats the food?</h3><p>A shopper may pick up biscuits at a local shop, bread at a supermarket or groceries through an app. Britannia may first sell to a distributor or retail business serving that shopper. Supplying stock into the channel and a consumer buying it are different events.</p><p>The group also sells overseas through its international operations and distribution arrangements. The underlying job is similar, but local preferences, currencies, shipping and retail channels can change the costs and risks.</p>${note(urls.company,'Britannia: bakery, dairy and adjacent snacking businesses')}${note(urls.annual,'Annual report: international business and distribution')}</section>`;
 const specifics=`<section class="content-section company-primer" id="britannia-specifics"><div class="number">HOW THIS BUSINESS WORKS</div><h2>A recipe becomes a business when people keep buying.</h2><ol class="primer-route"><li><strong>Arrange ingredients and packaging</strong><span>Source flour, sugar, edible oils, milk and other inputs appropriate to the product. Cost and quality both matter.</span></li><li><strong>Make consistent food safely</strong><span>Use manufacturing facilities and relevant production partners, control recipes and quality, and package products for their intended storage conditions.</span></li><li><strong>Supply the right outlet</strong><span>Move stock through distribution and retail channels. The range, delivery frequency and storage requirements differ across foods.</span></li><li><strong>Make the next purchase worthwhile</strong><span>Taste, affordability, availability and trust help a shopper choose again. Competing products are only a shelf or a tap away.</span></li></ol><p>This is a simplified route. The group uses different entities, partners and arrangements across products and markets; not every offering follows the same factory-to-shop path.</p>${note(urls.annual,'Annual report: operations, business strategy and food-quality controls')}
 <h3>What remains after a sale?</h3><p>The amount a shopper pays is not automatically Britannia’s recorded revenue. Discounts, promotions, channel margins, returns and applicable taxes affect the route from a retail purchase to company sales.</p><p>Revenue then has to cover ingredients, packaging, production, transport, people, advertising and other expenses. Selling more goods can help spread factory costs, but more revenue does not guarantee more profit or cash.</p><div class="primer-examples"><div><h4>A pack count can hide a quantity change</h4><p>A shopper can buy the same number of packs while receiving less food if the weight per pack changes.</p><span>Read quantity or volume measures on a consistent basis, alongside prices and product mix.</span></div><div><h4>Availability needs the right stock</h4><p>Sending more goods to shops can raise channel stock before shoppers buy it. Unsold stock can later be discounted or returned.</p><span>Read distribution commentary alongside inventory, returns and customer amounts still due.</span></div><div><h4>Freshness changes the delivery problem</h4><p>Bread, biscuits and dairy have different shelf lives and storage needs. Faster sales are useful only if the supply route preserves quality at an acceptable cost.</p><span>Do not assume all dairy products require the same storage or all bakery products have the same shelf life.</span></div></div>${note(urls.annual,'Annual report: revenue recognition and sales reconciliation','Consolidated Notes 29 and 53')}
 <h3>Understand the core business before the expansion story</h3><p>Britannia groups its activities around bakery, dairy and adjacent snacking. A new flavour can use an existing brand and distribution route; a newer category can require different equipment, storage, partners and advertising. Those are different growth tasks.</p><p>For dairy, ask how milk sourcing, processing and distribution fit together. For croissants and wafers, ask whether consumer awareness becomes repeat demand. For all categories, <strong>capacity</strong> is the ability to produce; <strong>utilisation</strong> is how much of that ability is actually used.</p>
 <h3>Why the cheese partnership matters</h3><p>Britannia Bel Foods combines Britannia’s and Bel’s involvement in a jointly controlled cheese business. A <strong>joint venture</strong> means the partners share control under their agreement; it is different from a business controlled by Britannia alone.</p><p>Under the <strong>equity method</strong>, the group recognises its share of the venture’s profit or loss rather than adding every cheese sale to group revenue. Understand that relationship before comparing a cheese brand with a biscuit brand. The dated partnership announcement explains the manufacturing arrangement; the annual accounts explain the reporting treatment.</p>${note(urls.cheese,'Official cheese manufacturing announcement','9 October 2024')}${note(urls.annual,'Annual report: joint-venture accounting and investment','Consolidated accounting policy and Notes 7 and 43')}
 <details class="primer-detail"><summary>Useful words in Britannia’s reports</summary><dl class="primer-glossary">${[
 ['Volume, price and mix','Volume describes quantities on the stated basis; price is what is realised per unit; mix is the balance of products sold. Pack sizes must be considered when comparing quantities.'],
 ['General trade, modern trade and quick commerce','Local shops, organised retail chains and fast-delivery shopping platforms are different routes to shoppers. Their terms, promotions and stock needs can differ.'],
 ['Margin','A specified profit measure divided by the corresponding revenue. Identify the costs included before comparing periods or other food companies.'],
 ['Inventory and working capital','Inventory is stock held for production or sale. Customer amounts due, supplier payments and stock affect the cash needed to keep the business running.'],
 ['Stock returns','Goods returned through the sales channel. Britannia’s sales note separately reconciles returns and discounts to recorded sales; interpret them with the related sales base.'],
 ['Consolidated and standalone','Standalone is the parent company’s accounts. Consolidated accounts include subsidiaries and the specified treatment of associates and joint ventures. Do not switch bases halfway through a comparison.'],
 ['Non-controlling interests','The part of subsidiary results belonging to other owners. Group profit after tax can therefore differ from profit attributable to Britannia’s owners.']
 ].map(([term,meaning])=>`<div><dt>${term}</dt><dd>${meaning}</dd></div>`).join('')}</dl></details><p class="source-note">Business explanations checked 29 October 2026 using the linked FY 2025–26 report and official portfolio. Investigation prompts explain what to assess; they do not establish that a launch, factory or sales channel earns an attractive return.</p></section>`;
 function numbers(){const f=window.COMPANY_FINANCIALS[id],p=f.context,fmt=n=>new Intl.NumberFormat('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);return `<div class="primer-number-guide"><h3>What can the product mix tell us?</h3><p>The FY 2025–26 business responsibility report gives the approximate turnover mix below. It groups bakery and salted snacks together; <strong>it is not a biscuit-only sales split or a profit breakdown</strong>. The report states a consolidated reporting boundary unless otherwise specified.</p><table class="financial-table"><caption class="sr-only">Britannia FY 2025–26 approximate turnover mix, BRSR. No category profit allocation.</caption><thead><tr><th scope="col">Reported product grouping</th><th scope="col">Approximate share of turnover<br><small>Reported · %</small></th></tr></thead><tbody>${p.turnoverMix.map(r=>`<tr><th scope="row">${esc(r.name)}</th><td>~${r.share}%</td></tr>`).join('')}</tbody></table><p>Bakery and salted snacks dominate this mix. The table does not tell us the separate sales or profit of Good Day, Marie Gold, cheese or any other brand. Multiplying rounded shares by group revenue would not create an exact category-sales disclosure.</p>${note(f.source,'Official turnover-mix source','BRSR · item 13 reporting boundary and item 17 products/services · printed pages 107–108')}
 <details class="primer-detail"><summary>Where does reported group revenue come from?</summary><p>Consolidated Note 43 reports revenue by geographical market, including other operating revenue. These figures cover the same period and total as the company revenue above; they do not give separate geographical profits.</p><table class="financial-table"><caption class="sr-only">Britannia consolidated revenue by geographical market, FY 2025–26.</caption><thead><tr><th scope="col">Geographical market</th><th scope="col">Revenue<br><small>₹ crore</small></th></tr></thead><tbody>${p.geographies.map(r=>`<tr><th scope="row">${esc(r.name)}</th><td>${fmt(r.revenue)}</td></tr>`).join('')}</tbody><tfoot><tr><th scope="row">Total revenue from operations</th><td>${fmt(f.rows[0].revenue)}</td></tr></tfoot></table>${note(f.source,'Official geography disclosure','Consolidated Note 43 · printed page 309')}</details>
 <h3>Read the sales and profit definitions carefully</h3><p>Sale of goods of ₹${fmt(p.goods)} crore plus other operating revenue of ₹${fmt(p.otherOperating)} crore gives revenue from operations of ₹${fmt(f.rows[0].revenue)} crore. Other income is separate. The report’s other operating revenue includes items such as scrap sales, royalty income and government incentives; it is not all biscuit sales.</p><p>Group profit after tax is ₹${fmt(p.groupPat)} crore. Of that, ₹${fmt(p.nonControlling)} crore belongs to non-controlling interests, leaving ₹${fmt(f.rows[0].profit)} crore attributable to the owners of Britannia, the figure in the main table. These are different labelled measures, not conflicting versions of the same number.</p>${note(f.source,'Official sales and profit reconciliation','Consolidated statement of profit and loss · printed page 261; Notes 29 and 53')}
 <details class="primer-detail"><summary>What do the accounts show about the cheese joint venture?</summary><p>For FY 2025–26, Note 7 reports Britannia Bel Foods’ loss for the year of ₹${fmt(p.jointVenture.loss)} crore and Britannia’s ${p.jointVenture.interest}% interest. The consolidated related-party note records a share of loss in that joint venture of <strong>−₹${fmt(p.jointVenture.shareOfLoss)} crore</strong>.</p><p>This is an entity-level joint-venture result, not a profit margin for a cheese pack or a result for every dairy product. The equity-method share of loss affects group earnings; the venture’s full sales are not simply added to consolidated revenue.</p>${note(f.source,'Official joint-venture disclosures','Consolidated Notes 7 and 45 · printed pages 284 and 313')}</details><p>Next, read operating cash flow, inventory, customer and supplier balances, capital spending, debt and dividends. Those checks help establish whether reported earnings translate into cash and how that cash is used.</p></div>`}
 if(window.PRODUCT_VISUALS){const old=window.PRODUCT_VISUALS[id].map(p=>p.name==='NutriChoice'?{...p,category:'Biscuits and snacks'}:p),first=[old.find(p=>p.name==='Good Day'),old.find(p=>p.name==='Cheese')].filter(Boolean);const drawings=[['Britannia Bread','Bakery · bread','bread'],['Britannia Cakes','Bakery · packaged cakes','cakes'],['Toastea Rusk','Bakery · rusk','rusk']].map(([name,category,slug])=>({name,category,url:urls.annual,image:`assets/products/britannia-business-${slug}.svg`,kind:'illustration',alt:`${name} — conceptual illustration, not a product photograph`}));window.PRODUCT_VISUALS[id]=[...first,...drawings,...old.filter(p=>!first.includes(p))];}
 window.companyPrimer={skipBusiness(company){return company.id===id||!!previous?.skipBusiness(company);},render(company,slot){if(company.id!==id)return previous?.render(company,slot)||'';return slot==='basics'?basics:slot==='specifics'?specifics:slot==='numbers'?numbers():'';},contents(company){return company.id===id?[['britannia-basics','Britannia from the basics'],['britannia-specifics','How Britannia works']]:previous?.contents(company)||[]}};
})();
